    def sample(rng, dim, lb, ub):
        return rng.uniform(lb, ub, size=dim)

    def clip(candidates, lb, ub):
        clipped = []
        for candidate in candidates:
            clipped_candidate = np.clip(candidate, lb, ub)
            clipped.append(clipped_candidate)
        return clipped

    best_solution = None
    best_fitness = float('inf')
    iterations = 0

    while iterations < budget:
        solution = sample(rng, dim, lb, ub)
        fitness = func(solution)

        if fitness < best_fitness:
            best_solution = solution
            best_fitness = fitness

        iterations += 1

    return best_solution

